  Definition fwin_o (LF : list fframe) (k ff : Z) (iv : Z * Z) : Prop :=
    aceil <= fst iv
    \/ (ff <= fst iv /\ snd iv <= ff + fsz k)
    \/ (Z.shiftr ff 3 + 2147450880 <= fst iv /\ snd iv <= Z.shiftr ff 3 + 2147450880 + fshn k)
    \/ (fst iv = AERRNO /\ snd iv = AERRNO + 4)
    \/ (exists O n, fsobj H LF O n /\ aapp O n /\ 0 <= n /\ O <= fst iv /\ snd iv <= O + n).
